t_ninja	*summon_naruto(t_scroll *scroll, int chakra_cost)
{
	if (!scroll->is_active || scroll->chakra < chakra_cost)
		return (NULL);
	scroll->chakra -= chakra_cost;
	return (create_jutsu("Rasengan", scroll->user));
}

typedef struct	s_goku
{
	int			level;
	unsigned long	power;
	char			ssj_color[16];
	bool			mastered;
	t_transformation	*forms;
	int			kaio_ken_multiplier;
}	t_saiyan;

void	activate_devil_fruit(t_pirate *luffy, e_fruit_type type)
{
	if (luffy->fruit_type == type && type == PARAMECIA)
	{
		luffy->is_rubber = true;
		luffy->cannot_swim = true;
		luffy->haki_level += 50;
	}
}

typedef struct	s_shinigami
{
	bool	death_note_active;
	bool	shinigami_eyes;
	int		remaining_lifespan;
	char	*current_owner_name;
	t_realm	*origin_realm;
	bool	loves_apples;
}	t_shinigami;

t_hollow	*hollow_resurrection(t_ichigo *ichigo, bool is_critical)
{
	if (is_critical && ichigo->spirit_energy > 1000)
	{
		ichigo->form = VASTO_LORDE;
		return (merge_all_powers(ichigo));
	}
	return (NULL);
}

t_titan	*titan_shift(t_eldian *hero, t_coordinate *coord)
{
	if (hero->willpower < 100 || !hero->is_wounded)
		return (NULL);
	hero->stamina -= 50;
	return (transform(hero, coord->power_source));
}

typedef struct	s_breath
{
	char	*breathing_style_name;
	char	*form_technique_name;
	int		power_multiplier;
	bool	sun_compatibility;
	int		stamina_drain_rate;
	bool	mark_active;
}	t_breath;

typedef enum	e_nen_type
{
	ENHANCER = 1,
	EMITTER = 2,
	TRANSMUTER = 3,
	CONJURER = 4,
	MANIPULATOR = 5,
	SPECIALIST = 6,
	UNKNOWN_TYPE = 0
}	t_nen_category;

void	automail_upgrade(t_alchemist *edward, e_metal type)
{
	int	i = 0;

	while (i < MAX_LIMBS)
	{
		if (edward->limbs[i].is_mechanical)
			edward->limbs[i].material = type;
		i++;
	}
}

void	add_pirate_member(t_crew *crew, t_pirate *member)
{
	if (crew->count < MAX_MEMBERS && member->bounty > MIN_BOUNTY)
	{
		crew->members[crew->count++] = member;
		crew->total_bounty += member->bounty;
	}
}

void	BANKAI(t_ichigo *kurosaki)
{
	if (kurosaki->spirit_pressure > 9000 && !kurosaki->is_exhausted)
	{
		activate_zangetsu(kurosaki->sword);
		kurosaki->speed *= 10;
		kurosaki->outfit_color = BLACK;
	}
}

t_alchemist	*transmute(t_exchange *law, bool use_stone)
{
	if (use_stone || law->gain == law->loss)
		return (create_object(law->target_material));
	return (NULL);
}

void	domain_expansion(t_gojo *satoru, int duration)
{
	if (satoru->cursed_energy > 500)
	{
		satoru->unlimited_void = true;
		stun_all_enemies(satoru->range, duration);
		satoru->cursed_energy -= 500;
	}
}

typedef struct	s_death_note
{
	char	*victim_full_name;
	int		seconds_to_die;
	void	(*cause_of_death)(t_person *);
	bool	face_is_known;
	t_shinigami	*attached_god;
}	t_note;

t_titan	*founding_titan_call(t_path *path, t_eldian *target)
{
	if (path->has_royal_blood && path->is_connected)
		return (awaken_the_rumbling(target));
	return (NULL);
}

void	gear_fifth(t_luffy *joyboy)
{
	joyboy->ridiculous_power = true;
	luffy->heartbeat = DRUMS_OF_LIBERATION;
	luffy->is_white_form = true;
	world_physics_override(joyboy->range);
}

t_hero	*one_for_all(t_quirk *stockpile, t_person *successor)
{
	if (successor->will_to_save > 100)
		return (pass_power(successor, stockpile->strength + stockpile->added_power));
	return (NULL);
}

void	kamehameha(t_goku *saiyan, int multiplier)
{
	while (saiyan->charging && saiyan->ki < MAX_KI)
		saiyan->ki += (1000 * multiplier);
	fire_energy_beam(saiyan->ki);
	saiyan->ki = 0;
}

typedef enum	e_beherit_type
{
	BEHERIT_DORMANT = 0,
	BEHERIT_GREEN = 1,
	BEHERIT_BLUE = 2,
	BEHERIT_SILVER = 3,
	BEHERIT_CRIMSON_EGG = 4,
	BEHERIT_AWAKENED = 5
}	t_beherit;

void	rewrite_reality(t_madoka *goddess)
{
	if (goddess->hope > goddess->despair)
	{
		delete_all_witches_from_history();
		goddess->is_conceptual_law = true;
		goddess->existence_erased = true;
	}
}

void	shinra_tensei(t_pain *nagato, t_target *target)
{
	if (nagato->chakra_level >= 100)
	{
		nagato->chakra_level -= 100;
		push_away_everything(target, FORCE_MAXIMUM);
		city_destroyed = true;
	}
}

t_cursed_tool	*toji_inventory(t_spirit *worm, int index)
{
	if (worm->is_hidden && index < worm->storage_capacity)
		return (worm->stored_items[index]);
	return (NULL);
}

void	za_warudo(t_dio *vampire, int max_seconds)
{
	stop_time(max_seconds);
	while (vampire->stamina > 0 && vampire->time_frozen)
	{
		throw_multiple_knives(vampire->target_coordinates);
		vampire->stamina -= 5;
	}
}

typedef struct	s_demon_slayer
{
	char	*slayer_name;
	char	*breathing_style;
	int		slayer_rank;
	bool	slayer_mark_active;
	t_sword	*nichirin_blade;
	bool	transparent_world;
}	t_slayer;

t_nen_user	*gon_transformation(t_hunter *gon)
{
	if (gon->total_despair > 9000)
	{
		gon->sacrifice_all = true;
		gon->nen_power = LIMITLESS;
		return (force_biological_aging(gon, ADULT_FORM));
	}
	return (NULL);
}

void	amaterasu(t_itachi *uchiha, t_eye *target_eye)
{
	uchiha->is_using_mangekyou = true;
	uchiha->eye_bleeding = true;
	spawn_eternal_black_fire(uchiha->vision_point);
	uchiha->stamina -= 80;
}

t_contract	*make_wish(t_kyubey *alien, t_girl *target)
{
	if (target->hope_potential > target->despair_potential)
	{
		spawn_soul_gem(target);
		return (create_new_magical_girl(target));
	}
	return (NULL);
}

void	full_counter(t_meliodas *dragon, t_magic *attack)
{
	if (attack->is_magic && dragon->is_active)
	{
		reflect_attack_back(attack->power * 2);
		dragon->stamina -= 20;
	}
}

typedef enum	e_beherit_state
{
	STATE_DORMANT = 0,
	STATE_AWAKENED = 1,
	STATE_SACRIFICE_READY = 2,
	STATE_ECLIPSE_TRIGGERED = 3,
	STATE_GOD_HAND_SUMMONED = 4
}	t_beherit_status;

void	rewrite_fate(t_homura *demon, t_madoka *target)
{
	while (target->is_alive == false || target->is_witch == true)
	{
		homura->time_loops_count++;
		homura->despair_level += 10;
		perform_time_reset(target);
	}
}
